<?php
function hidden($k,$v):void{echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function check($key,$title,$value=true,$attrs=''):void{echo '<label class="switch-row"><input type="checkbox" name="'.e($key).'" '.($value?'checked':'').' '.$attrs.'> '.e($title).'</label>';}
function deleteButton($action,$id,$text='حذف'):void{formstart($action);hidden('id',$id);echo '<button class="button secondary small" data-confirm="آیا از این عملیات مطمئن هستید؟">'.e($text).'</button></form>';}
function options($table,$where='1=1'):array{return ['0'=>'انتخاب نشده']+array_column(q("SELECT id,name FROM $table WHERE $where ORDER BY name")->fetchAll(),'name','id');}
function adminStaff():void{need('staff');$id=(int)($_GET['id']??0);$u=$id?q('SELECT * FROM staff WHERE id=? AND deleted=0',[$id])->fetch():null;layout('staff','همکاران و دسترسی‌ها','حساب مستقل، محدوده اطلاعات و مجوز هر عملیات را تعیین کنید.');echo '<section class="panel form-panel"><div class="staff-cards">';foreach(q('SELECT id,name,username,role,active FROM staff WHERE deleted=0 ORDER BY id')->fetchAll() as $r){echo '<a class="staff-card" href="/staff?id='.$r['id'].'#edit"><span class="mini-avatar">'.e(mb_substr($r['name'],0,1)).'</span><strong>'.e($r['name']).'</strong><small>'.e($r['username']).' · '.($r['active']?'فعال':'غیرفعال').'</small></a>';}echo '</div><a class="text-link" href="/staff">افزودن همکار جدید +</a></section>';
 $importedPractitioners=q("SELECT sp.source_name,m.staff_id,s.name,s.username,s.active,COUNT(e.id) visit_count
   FROM import_source_practitioner_map m
   JOIN import_source_practitioners sp ON sp.id=m.source_practitioner_id
   JOIN staff s ON s.id=m.staff_id
   LEFT JOIN import_patient_events e ON e.therapist_id=s.id
   GROUP BY sp.id,sp.source_name,m.staff_id,s.name,s.username,s.active
   ORDER BY visit_count DESC,sp.source_name")->fetchAll();
 if($importedPractitioners){echo '<section class="panel form-panel"><div class="panel-header"><h2>درمانگرهای واردشده از بقراط</h2><span class="count">'.fa(count($importedPractitioners)).'</span></div><p class="hint">این حساب‌ها هنگام انتقال به‌صورت غیرفعال ساخته شده‌اند و تا زمانی که مدیر آن‌ها را فعال و برایشان رمز تعیین نکند امکان ورود ندارند.</p><div class="table-scroll"><table><thead><tr><th>نام در بقراط</th><th>پروفایل مسیحا</th><th>ویزیت تاریخی</th><th>وضعیت ورود</th><th></th></tr></thead><tbody>';foreach($importedPractitioners as $r)echo '<tr><td>'.e($r['source_name']).'</td><td>'.e($r['name']).'<small>'.e($r['username']).'</small></td><td>'.fa($r['visit_count']).'</td><td>'.($r['active']?'فعال':'غیرفعال').'</td><td><a href="/staff?id='.(int)$r['staff_id'].'#edit">مدیریت</a></td></tr>';echo '</tbody></table></div></section>';}
 if(allowed($id?'staff.edit':'staff.create')&&(!$u||$u['role']!=='admin'||user()['role']==='admin')){echo '<section class="panel form-panel" id="edit">';sectiontitle($id?'ویرایش همکار':'ساخت همکار');formstart('staff');hidden('id',$id);echo '<div class="form-grid">';field('name','نام و نام خانوادگی',$u['name']??'','text','نام نمایشی در نوبت‌ها و گزارش‌ها.',true);field('username','نام کاربری',$u['username']??'','text','حداقل سه حرف انگلیسی یا عدد.',true);field('password','رمز ورود جدید','','password','حداقل ۱۲ نویسه. برای حفظ رمز فعلی خالی بگذارید.',!$id);$roles=['reception'=>'پذیرش','therapist'=>'درمانگر','finance'=>'امور مالی'];if(user()['role']==='admin')$roles=['admin'=>'مدیر کلینیک']+$roles;selectfield('role','نقش پایه',$roles,$u['role']??'reception','مدیر به همه بخش‌ها دسترسی دارد؛ سایر نقش‌ها از تنظیمات جزئی پیروی می‌کنند.',true);echo '</div>';check('active','حساب فعال',$u['active']??true);formend('ذخیره همکار','/staff');if($id&&allowed('staff.delete')&&$u['role']!=='admin')deleteButton('staff_delete',$id,'حذف حساب');echo '</section>';}
 if($u&&$u['role']!=='admin'&&user()['role']==='admin'){$p=permissions($u);echo '<section class="panel form-panel">';sectiontitle('دسترسی‌های '. $u['name'],'تغییرات پس از ذخیره فوراً در همه درخواست‌ها اعمال می‌شوند.');formstart('permissions');hidden('id',$id);echo '<div class="form-grid">';foreach(['profile'=>'مشاهده پروفایل مراجع','contact'=>'مشاهده اطلاعات تماس','forms.visit'=>'فرم‌های ویزیت و درمان','forms.general'=>'فرم‌های عمومی'] as $k=>$v)selectfield('scope['.str_replace('.','_',$k).']',$v,str_starts_with($k,'forms.')?['none'=>'هیچ فرم','own'=>'فقط فرم‌های ثبت‌شده توسط خود کاربر','all'=>'همه فرم‌های مراجع مجاز']:['none'=>'هیچ‌کس','related'=>'فقط مراجع مرتبط','all'=>'همه مراجعین'],$p[$k],'مراجع مرتبط: ثبت‌کننده پرونده، مسئول پرونده یا درمانگر دارای جلسه.');echo '</div>';foreach(permissionGroups() as $group=>$items){echo '<fieldset class="permission-group"><legend>'.e($group).'</legend><div class="actions"><button type="button" class="button secondary small" data-check-group="1">انتخاب همه</button><button type="button" class="button secondary small" data-check-group="0">عدم دسترسی به همه</button></div><div class="permission-grid">';foreach($items as $k=>$title)check('perm['.str_replace('.','_',$k).']',$title,$p[$k]);echo '</div></fieldset>';}formend('ذخیره دسترسی‌ها','/staff');echo '</section>';}endLayout();}
function labelsView():void{need('labels');$id=(int)($_GET['id']??0);$r=$id?q('SELECT * FROM labels WHERE id=? AND deleted=0',[$id])->fetch():null;layout('labels','لیبل‌های مراجعین','برچسب رنگی برای تشخیص سریع نوع مراجعه؛ لیبل پیش‌فرض هنگام نوبت‌دهی اعمال می‌شود.');echo '<section class="panel form-panel"><div class="staff-cards">';foreach(q('SELECT * FROM labels WHERE deleted=0')->fetchAll() as $v){echo '<div class="staff-card"><span class="badge" style="color:'.e($v['color']).'">'.e($v['name']).'</span><small>'.($v['is_default']?'پیش‌فرض · ':'').($v['active']?'فعال':'غیرفعال').'</small>';if(allowed('labels.edit'))echo '<a href="?id='.$v['id'].'">ویرایش</a>';if(allowed('labels.delete'))deleteButton('label_delete',$v['id']);echo '</div>';}echo '</div></section>';if(allowed($id?'labels.edit':'labels.create')){echo '<section class="panel form-panel">';formstart('label_save');hidden('id',$id);echo '<div class="form-grid">';field('name','عنوان لیبل',$r['name']??'','text','مانند مراجعه اول یا دوره توان‌بخشی.',true);field('color','رنگ',$r['color']??'#087f75','color','رنگ نمایش لیبل.',true);echo '</div>';check('active','فعال',$r['active']??true);check('is_default','لیبل پیش‌فرض سامانه',$r['is_default']??false);formend('ذخیره لیبل','/labels');echo '</section>';}endLayout();}
function inventoryView():void{
 need('inventory');$id=(int)($_GET['id']??0);$item=$id?q('SELECT * FROM inventory_items WHERE id=?',[$id])->fetch():null;
 layout('inventory','انبار و کالا','کالاهای جاری مسیحا و سابقه مصرف منتقل‌شده از بقراط.');
 $items=q("SELECT i.*,
   CASE WHEN i.opening_quantity IS NULL THEN NULL ELSE i.opening_quantity+COALESCE(SUM(CASE WHEN m.affects_stock=1 THEN m.quantity_delta ELSE 0 END),0) END current_stock,
   -COALESCE(SUM(CASE WHEN m.movement_type='historical_usage' THEN m.quantity_delta ELSE 0 END),0) historical_usage
   FROM inventory_items i LEFT JOIN inventory_movements m ON m.item_id=i.id
   GROUP BY i.id ORDER BY i.active DESC,i.name")->fetchAll();
 echo '<section class="panel"><div class="panel-header"><h2>کالاها</h2><span class="count">'.fa(count($items)).'</span></div><div class="table-scroll"><table><thead><tr><th>کالا</th><th>واحد</th><th>قیمت فروش</th><th>موجودی جاری</th><th>مصرف تاریخی بقراط</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>';
 foreach($items as $v){echo '<tr><td>'.e($v['name']).'</td><td>'.e($v['unit']).'</td><td>'.money($v['sale_price_toman']).'</td><td>'.($v['current_stock']===null?'تعیین نشده':fa(rtrim(rtrim(number_format((float)$v['current_stock'],3,'.',''),'0'),'.'))).'</td><td>'.fa(rtrim(rtrim(number_format((float)$v['historical_usage'],3,'.',''),'0'),'.')).'</td><td>'.($v['active']?'فعال':'غیرفعال').'</td><td><a href="/inventory?id='.$v['id'].'">مدیریت</a></td></tr>';}
 echo '</tbody></table></div></section>';
 echo '<section class="panel form-panel">';sectiontitle($item?'ویرایش کالا':'کالای جدید');formstart('inventory_item_save');hidden('id',$id);echo '<div class="form-grid">';field('name','نام کالا',$item['name']??'','text','نام کالا در انبار و گزارش.',true);field('unit','واحد',$item['unit']??'عدد','text','مانند عدد، بسته، جفت.',true);field('sale_price_toman','قیمت فروش (تومان)',$item['sale_price_toman']??0,'number','قیمت جاری کالا.',true,false,'min="0"');echo '</div>';check('active','کالا فعال',$item['active']??true);formend('ذخیره کالا','/inventory');echo '</section>';
 if($item){echo '<div class="dashboard-grid"><section class="panel form-panel">';sectiontitle('موجودی شروع','مصرف تاریخی بقراط روی موجودی جاری اثر نمی‌گذارد. موجودی واقعی را از اینجا تعیین کنید.');formstart('inventory_opening');hidden('item_id',$id);field('opening_quantity','موجودی شروع',$item['opening_quantity']??'','number','موجودی واقعی در تاریخ شروع.',true,false,'min="0" step="0.001"');field('opening_as_of','تاریخ موجودی',($item['opening_as_of']??date('Y-m-d')),'date','تاریخی که موجودی شمارش شده است.',true);formend('ثبت موجودی شروع','/inventory?id='.$id);echo '</section><section class="panel form-panel">';sectiontitle('تعدیل موجودی','برای ورود، خروج، اصلاح شمارش یا کسری/اضافه موجودی.');formstart('inventory_adjust');hidden('item_id',$id);field('quantity_delta','تغییر موجودی','','number','مثبت: افزایش؛ منفی: کاهش.',true,false,'step="0.001"');field('occurred_on','تاریخ',date('Y-m-d'),'date','تاریخ اعمال تغییر.',true);field('note','شرح','','text','علت تعدیل.',true);formend('ثبت تعدیل','/inventory?id='.$id);echo '</section></div>';
 $moves=q("SELECT m.*,p.fname,p.lname FROM inventory_movements m LEFT JOIN patients p ON p.pid=m.pid WHERE m.item_id=? ORDER BY COALESCE(m.occurred_on,DATE(m.created_at)) DESC,m.id DESC LIMIT 100",[$id])->fetchAll();
 echo '<section class="panel form-panel"><h2>گردش کالا</h2><div class="table-scroll"><table><thead><tr><th>تاریخ</th><th>نوع</th><th>تعداد</th><th>مبلغ</th><th>بیمار</th><th>کد نوبت</th><th>اثر بر موجودی</th><th>شرح</th></tr></thead><tbody>';
 $labels=['historical_usage'=>'مصرف تاریخی بقراط','adjustment'=>'تعدیل','purchase'=>'ورود','sale'=>'فروش','return'=>'برگشت'];
 foreach($moves as $m)echo '<tr><td>'.jd($m['occurred_on']?:substr($m['created_at'],0,10)).'</td><td>'.e($labels[$m['movement_type']]??$m['movement_type']).'</td><td>'.fa(rtrim(rtrim(number_format((float)$m['quantity_delta'],3,'.',''),'0'),'.')).'</td><td>'.($m['total_toman']===null?'—':money($m['total_toman'])).'</td><td>'.($m['pid']?e(patientName($m)):'—').'</td><td>'.fa($m['appointment_code']?:'—').'</td><td>'.($m['affects_stock']?'بله':'خیر').'</td><td>'.e($m['note']).'</td></tr>';
 echo '</tbody></table></div></section>';}
 endLayout();
}
function servicesView():void{need('services');$tab=$_GET['tab']??'services';$id=(int)($_GET['id']??0);layout('services','خدمات و پکیج‌ها','تعرفه، دسته‌بندی، خدمات همکاران و سهم درمانگر.');echo '<nav class="tab-nav">';foreach(['services'=>'خدمات','tariffs'=>'تعرفه‌ها','source'=>'کاتالوگ بقراط','categories'=>'دسته‌بندی‌ها','packages'=>'پکیج‌ها','shares'=>'خدمات و سهم همکار'] as $k=>$title)echo '<a class="'.($tab===$k?'selected':'').'" href="?tab='.$k.'">'.$title.'</a>';echo '</nav>';
 if($tab==='tariffs'){
  $tariffId=(int)($_GET['tariff_id']??0);$tariff=$tariffId?q('SELECT * FROM service_tariffs WHERE id=? AND deleted=0',[$tariffId])->fetch():null;
  $rows=q("SELECT t.*,s.name service_name FROM service_tariffs t JOIN services s ON s.id=t.service_id WHERE t.deleted=0 AND s.deleted=0 ORDER BY t.active DESC,t.effective_from DESC,t.id DESC")->fetchAll();
  echo '<section class="panel"><div class="panel-header"><h2>تعرفه‌های خدمات</h2><span class="count">'.fa(count($rows)).'</span></div><div class="table-scroll"><table><thead><tr><th>خدمت</th><th>نوع</th><th>عنوان</th><th>قرارداد</th><th>مبلغ</th><th>بازه اجرا</th><th>وضعیت</th><th></th></tr></thead><tbody>';
  foreach($rows as $v){$type=$v['tariff_type']==='contract'?'قراردادی':'عادی';echo '<tr><td>'.e($v['service_name']).'</td><td>'.$type.'</td><td>'.e($v['title']).'</td><td>'.e($v['contract_name']?:'—').'</td><td>'.money($v['price_toman']).'</td><td>'.jd($v['effective_from']).' تا '.($v['effective_to']?jd($v['effective_to']):'بدون پایان').'</td><td>'.($v['active']?'فعال':'غیرفعال').'<small>'.e($v['source_system']==='boghrat'?'پایه انتقال از بقراط':'مسیحا').'</small></td><td><a href="?tab=tariffs&tariff_id='.(int)$v['id'].'#tariff-edit">ویرایش</a></td></tr>';}
  echo '</tbody></table></div></section><section class="panel form-panel" id="tariff-edit">';sectiontitle($tariff?'ویرایش تعرفه':'تعرفه جدید','تعرفه عادی، قیمت پیش‌فرض خدمت است؛ تعرفه قراردادی هنگام نوبت قابل انتخاب است.');formstart('tariff_save');hidden('tariff_id',$tariffId);echo '<div class="form-grid">';selectfield('service_id','خدمت',options('services','deleted=0'),$tariff['service_id']??0,'خدمت مرتبط با تعرفه.',true);selectfield('tariff_type','نوع تعرفه',['normal'=>'عادی','contract'=>'قراردادی'],$tariff['tariff_type']??'normal','تعرفه قراردادی نام قرارداد هم نیاز دارد.',true);field('title','عنوان تعرفه',$tariff['title']??'تعرفه عادی','text','مثلاً تعرفه عادی یا تعرفه قرارداد شرکت.',true);field('contract_name','نام قرارداد / سازمان',$tariff['contract_name']??'','text','برای تعرفه عادی خالی بگذارید.');field('price_toman','مبلغ (تومان)',$tariff['price_toman']??0,'number','مبلغ این تعرفه.',true,false,'min="0"');field('effective_from','شروع اجرا',$tariff['effective_from']??date('Y-m-d'),'date','تاریخ شروع اعتبار تعرفه.',true);field('effective_to','پایان اجرا',$tariff['effective_to']??'','date','اختیاری؛ خالی یعنی بدون پایان.');echo '</div>';check('active','تعرفه فعال',$tariff['active']??true);formend('ذخیره تعرفه','/services?tab=tariffs');if($tariffId)deleteButton('tariff_delete',$tariffId,'بایگانی تعرفه');echo '</section>';
 }
 elseif($tab==='source'){
  $srcServices=q("SELECT c.source_name,COUNT(x.id) uses_count,MIN(x.amount_toman) min_price,MAX(x.amount_toman) max_price,s.id service_id,s.name mapped_name,s.price mapped_price,m.mapping_mode FROM import_source_services c LEFT JOIN import_event_services x ON x.source_service_id=c.id LEFT JOIN import_source_service_map m ON m.source_service_id=c.id LEFT JOIN services s ON s.id=m.service_id GROUP BY c.id,c.source_name,s.id,s.name,s.price,m.mapping_mode ORDER BY uses_count DESC,c.source_name")->fetchAll();
  $srcGoods=q("SELECT c.source_name,COUNT(x.id) uses_count,COALESCE(SUM(x.quantity),0) quantity_total,MIN(x.amount_toman) min_price,MAX(x.amount_toman) max_price FROM import_source_goods c LEFT JOIN import_event_goods x ON x.source_goods_id=c.id GROUP BY c.id,c.source_name ORDER BY quantity_total DESC,c.source_name")->fetchAll();
  echo '<section class="panel form-panel"><div class="panel-header"><h2>خدمات کشف‌شده از بقراط</h2><span class="count">'.fa(count($srcServices)).'</span></div><p class="hint">فهرست فقط از سوابق واردشده ساخته شده و خدمات داخلی مسیحا را تغییر نمی‌دهد.</p><div class="table-scroll"><table><thead><tr><th>خدمت بقراط</th><th>دفعات</th><th>کمترین مبلغ</th><th>بیشترین مبلغ</th><th>خدمت داخلی مسیحا</th><th>تعرفه جاری</th></tr></thead><tbody>';
  foreach($srcServices as $v)echo '<tr><td>'.e($v['source_name']).'</td><td>'.fa($v['uses_count']).'</td><td>'.($v['min_price']===null?'—':money($v['min_price'])).'</td><td>'.($v['max_price']===null?'—':money($v['max_price'])).'</td><td>'.($v['service_id']?'<a href="/services?id='.(int)$v['service_id'].'#edit">'.e($v['mapped_name']).'</a>':'—').'</td><td>'.($v['service_id']?money($v['mapped_price']):'—').'</td></tr>';
  echo '</tbody></table></div></section>';
  echo '<section class="panel form-panel"><div class="panel-header"><h2>کالاهای کشف‌شده از بقراط</h2><span class="count">'.fa(count($srcGoods)).'</span></div><div class="table-scroll"><table><thead><tr><th>کالا</th><th>دفعات</th><th>تعداد کل</th><th>کمترین مبلغ</th><th>بیشترین مبلغ</th></tr></thead><tbody>';
  foreach($srcGoods as $v)echo '<tr><td>'.e($v['source_name']).'</td><td>'.fa($v['uses_count']).'</td><td>'.fa(rtrim(rtrim(number_format((float)$v['quantity_total'],3,'.',''),'0'),'.')).'</td><td>'.($v['min_price']===null?'—':money($v['min_price'])).'</td><td>'.($v['max_price']===null?'—':money($v['max_price'])).'</td></tr>';
  echo '</tbody></table></div></section>';
 }
 elseif($tab==='categories'){$r=$id?q('SELECT * FROM service_categories WHERE id=? AND deleted=0',[$id])->fetch():null;echo '<section class="panel form-panel">';foreach(q('SELECT * FROM service_categories WHERE deleted=0')->fetchAll() as $v){echo '<div class="resource-row"><strong>'.e($v['name']).'</strong><span>'.($v['active']?'فعال':'غیرفعال').'</span><a href="?tab=categories&id='.$v['id'].'">ویرایش</a>';deleteButton('category_delete',$v['id']);echo '</div>';}formstart('category_save');hidden('id',$id);field('name','نام دسته',$r['name']??'','text','دسته‌بندی خدمات کلینیک.',true);check('active','فعال',$r['active']??true);formend('ذخیره دسته','/services?tab=categories');echo '</section>';}
 elseif($tab==='packages'){$r=$id?q('SELECT * FROM packages WHERE id=? AND deleted=0',[$id])->fetch():null;$items=$id?array_column(q('SELECT * FROM package_items WHERE package_id=?',[$id])->fetchAll(),'quantity','service_id'):[];echo '<section class="panel form-panel">';foreach(q('SELECT * FROM packages WHERE deleted=0')->fetchAll() as $v){echo '<div class="resource-row"><div><strong>'.e($v['name']).'</strong><small>'.money($v['price']).' تومان · '.($v['auto_price']?'قیمت خودکار':'قیمت اختصاصی').' · '.($v['active']?'فعال':'غیرفعال').'</small></div><a href="?tab=packages&id='.$v['id'].'">ویرایش</a>';deleteButton('package_delete',$v['id']);echo '</div>';}echo '</section><section class="panel form-panel">';sectiontitle($id?'ویرایش پکیج':'پکیج جدید');formstart('package_save');hidden('id',$id);field('name','نام پکیج',$r['name']??'','text','عنوان بسته خدمات.',true);echo '<div class="package-items">';foreach(q('SELECT * FROM services WHERE deleted=0 ORDER BY name')->fetchAll() as $s)field('qty['.$s['id'].']',$s['name'].' · '.money($s['price']).' تومان',$items[$s['id']]??0,'number','تعداد این خدمت در پکیج؛ صفر یعنی خارج از پکیج.',false,false,'min="0" max="365" data-package-price="'.(int)$s['price'].'"');echo '</div><p class="notice" data-package-total>جمع خدمات: —</p>';check('auto_price','قیمت برابر جمع خدمات و به‌روزرسانی خودکار با تعرفه‌ها',$r['auto_price']??true);field('price','قیمت اختصاصی پکیج (تومان)',$r['price']??0,'number','فقط وقتی قیمت خودکار غیرفعال باشد اعمال می‌شود.',false,false,'min="0"');check('active','پکیج فعال',$r['active']??true);formend('ذخیره پکیج','/services?tab=packages');echo '</section>';}
