 field('sms_sender','شماره فرستنده',$cfg['sender']??'','text','اختیاری؛ خط خدماتی/تبلیغاتی ثبت‌شده در کاوه‌نگار.');
 echo '<div class="field"><label>وضعیت کلید API</label><div class="notice">'.(!empty($cfg['key'])?'کلید اتصال ثبت شده است.':'کلید اتصال ثبت نشده؛ از تنظیمات کلینیک وارد کنید.').'</div></div></div>';
 check('sms_notifications','فعال‌کردن ارسال پیامک‌های کلینیک',$enabled);
 echo '<p class="hint">تا وقتی این گزینه خاموش است، هیچ پیام خودکار یا گروهی ارسال نمی‌شود. قالب‌ها نیز جداگانه باید فعال شوند.</p>';
 formend('ذخیره تنظیمات پیامک','/sms');
 echo '</section>';

 echo '<section class="panel form-panel" id="templates"><div class="panel-header"><h2>قالب‌های خودکار</h2><span class="count">'.fa(count($templates)).'</span></div><p class="hint">متغیرهای قابل استفاده: {patient_name}، {first_name}، {clinic_name}، {clinic_phone}، {date}، {time}، {therapist}، {service}، {clinic}</p>';
 foreach($templates as $t){
  formstart('sms_template_save');hidden('event_key',$t['event_key']);
