  else hidden('send_offset_minutes',0);
  echo '</div>';check('enabled','این قالب فعال باشد',(bool)$t['enabled']);echo '<div class="form-actions"><button class="button primary" type="submit">ذخیره قالب</button></div></details></form>';
 }
 echo '</section>';

 echo '<section class="panel form-panel"><div class="panel-header"><h2>ارسال گروهی</h2><span class="muted">ارسال فقط پس از قرارگرفتن در صف انجام می‌شود.</span></div>';
 formstart('sms_campaign_queue');echo '<div class="form-grid">';
 field('title','عنوان داخلی','','text','فقط برای گزارش داخلی است.',true);
 selectfield('audience','دریافت‌کنندگان',['all_active'=>'تمام بیماران فعال','portal'=>'بیماران دارای پورتال فعال','debtors'=>'بیماران دارای مانده بدهی'],'portal','فقط پرونده‌های دارای موبایل معتبر وارد صف می‌شوند.',true);
 field('message','متن پیام','','textarea','متن دقیق پیام گروهی.',true,true);
 echo '</div>';formend('قرار دادن در صف','/sms');echo '</section>';

 $rows=q("SELECT o.*,p.fname,p.lname FROM sms_outbox o LEFT JOIN patients p ON p.pid=o.pid ORDER BY o.id DESC LIMIT 200")->fetchAll();
 echo '<section class="panel"><div class="panel-header"><div><h2>تاریخچه و صف پیامک</h2><p class="muted">آخرین ۲۰۰ پیام</p></div><form method="post">';csrf();echo '<input type="hidden" name="action" value="sms_process"><button class="button secondary" '.(!$enabled?'disabled':'').'>پردازش ۲۰ پیام</button></form></div>';
 if(!$rows)emptyState('هنوز پیامکی در صف نیست','پس از فعال‌سازی قالب‌ها یا ثبت ارسال گروهی، پیام‌ها اینجا دیده می‌شوند.');
 else{echo '<div class="table-scroll"><table><thead><tr><th>زمان</th><th>بیمار</th><th>نوع</th><th>گیرنده</th><th>وضعیت</th><th>تلاش</th><th>خطا</th><th></th></tr></thead><tbody>';$labels=['queued'=>'در صف','sending'=>'در حال ارسال','sent'=>'ارسال‌شده','failed'=>'ناموفق','cancelled'=>'لغوشده'];foreach($rows as $r){echo '<tr><td>'.jd($r['scheduled_at'],'yyyy/MM/dd HH:mm').'</td><td>'.($r['pid']?'<a href="/patient?id='.(int)$r['pid'].'">'.e(trim(($r['fname']??'').' '.($r['lname']??''))).'</a>':'—').'</td><td>'.e($r['event_key']).'</td><td>'.fa($r['mobile']).'</td><td>'.e($labels[$r['status']]??$r['status']).'</td><td>'.fa($r['attempts']).'</td><td>'.e($r['last_error']?:'—').'</td><td><div class="actions">';if(in_array($r['status'],['failed','cancelled'],true)){echo '<form method="post">';csrf();echo '<input type="hidden" name="action" value="sms_retry"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="button secondary small">تلاش مجدد</button></form>';}if(in_array($r['status'],['queued','failed'],true)){echo '<form method="post">';csrf();echo '<input type="hidden" name="action" value="sms_cancel"><input type="hidden" name="id" value="'.(int)$r['id'].'"><button class="button secondary small">لغو</button></form>';}echo '</div></td></tr>';}echo '</tbody></table></div>';}
 echo '</section>';
 endLayout();
