(q("SELECT name FROM resources WHERE kind='room' AND active=1")->fetchAll(),'name','name'),'','اختیاری؛ در صورت انتخاب، تداخل اتاق بررسی می‌شود.');field('notes','یادداشت','','textarea','توضیحات لازم برای پذیرش و درمانگر.',false,true);hidden('equipment','');echo '</div></section><aside><section class="info-card"><h2>نوبت‌دهی ساده و دقیق</h2><p>اطلاعات زمان به میلادی ذخیره می‌شوند و تقویم و تاریخ‌های نمایشی شمسی هستند.</p><p>تداخل درمانگر و بیمار پیش از ثبت بررسی می‌شود.</p></section></aside></div>';formend('ثبت نوبت','/appointments');endLayout();}
