  echo '</dl><div class="form-actions"><a class="button secondary" href="/forms?pid='.(int)$src['pid'].'">بازگشت به فرم‌های مراجعه</a><a class="button secondary" href="/patient?id='.(int)$src['pid'].'">پرونده بیمار</a></div></section>';endLayout();return;
 }
 $r=$id?q('SELECT * FROM clinic_forms WHERE id=? AND deleted=0',[$id])->fetch():null;
