    echo '<div class="table-scroll"><table><thead><tr><th>تاریخ</th><th>بیمار</th><th>نوع</th><th>مبلغ</th><th>روش</th><th>کد نوبت</th></tr></thead><tbody>';
    foreach($sourceRows as $r){$appt=$r['appointment_code']?:'';if(!$appt&&!empty($r['allocations'])){$parts=[];foreach(explode(',',$r['allocations']) as $piece){[$code,$amount]=array_pad(explode('|',$piece,2),2,'');$parts[]=fa($code).' · '.money((int)$amount).' ت';}$appt=implode(' / ',$parts);}echo '<tr><td>'.jd($r['tx_date']).'</td><td><a href="/patient?id='.(int)$r['pid'].'">'.e(patientName($r)).'</a></td><td>'.e($labels[$r['tx_type']]??$r['tx_type']).'</td><td>'.money($r['amount_toman']).'</td><td>'.e($r['method']?:'—').'</td><td>'.($appt?:'—').'</td></tr>';}
    echo '</tbody></table></div>';
  }
  if($canDebt){$sourceDebts=q("SELECT p.pid,p.fname,p.lname,SUM(l.debit_toman-l.credit_toman) balance
      FROM patient_account_ledger l JOIN patients p ON p.pid=l.pid
      WHERE l.voided=0 GROUP BY p.pid,p.fname,p.lname
      HAVING balance>0 ORDER BY balance DESC LIMIT 50")->fetchAll();
    if($sourceDebts){echo '<h3>مانده افتتاحیه / قبلی قابل پیگیری</h3><div class="table-scroll"><table><thead><tr><th>بیمار</th><th>مانده بدهی</th></tr></thead><tbody>';foreach($sourceDebts as $r)echo '<tr><td><a href="/patient?id='.(int)$r['pid'].'">'.e(patientName($r)).'</a></td><td>'.money($r['balance']).'</td></tr>';echo '</tbody></table></div>';}
  }
  echo '</section>';
 }
 if(!$report&&allowed('finance.pay')){
  $legacyOptions=[''=>'انتخاب بیمار دارای مانده قبلی'];foreach(q("SELECT p.pid,p.fname,p.lname,SUM(l.debit_toman-l.credit_toman) balance FROM patient_account_ledger l JOIN patients p ON p.pid=l.pid WHERE l.voided=0 GROUP BY p.pid,p.fname,p.lname HAVING balance>0 ORDER BY p.lname,p.fname")->fetchAll() as $lp)$legacyOptions[$lp['pid']]=patientName($lp).' — مانده '.money($lp['balance']).' تومان';
