  echo '<section class="panel form-panel"><div class="panel-header"><h2>عملکرد تاریخی درمانگران بقراط</h2><span class="muted">از داده ساختاریافته واردشده</span></div><p class="hint">فیلتر درمانگر روی شناسه داخلی مسیحا اعمال می‌شود. فیلتر کلینیک برای سوابق قدیمی بقراط قابل اعمال نیست چون کلینیک در هر ویزیت تاریخی به‌صورت مستقل ذخیره نشده است.</p><div class="table-scroll"><table><thead><tr><th>درمانگر</th><th>مراجع یکتا</th><th>کل ویزیت</th><th>ویزیت‌شده</th><th>غایب</th><th>کنسل</th><th>ارزش ثبت‌شده مراجعه</th></tr></thead><tbody>';
  foreach($historical as $r)echo '<tr><td>'.e($r['therapist']).'</td><td>'.fa($r['patients']).'</td><td>'.fa($r['visits']).'</td><td>'.fa($r['done_count']).'</td><td>'.fa($r['absent_count']).'</td><td>'.fa($r['cancelled_count']).'</td><td>'.money($r['charge_total']).'</td></tr>';
