      GROUP BY s.id,s.name ORDER BY uses_count DESC,s.name",$historicalArgs)->fetchAll();
  echo '<section class="panel form-panel"><h2>عملکرد تاریخی خدمات بقراط</h2><div class="table-scroll"><table><thead><tr><th>خدمت مسیحا</th><th>دفعات ثبت</th><th>مراجع یکتا</th><th>جمع مبلغ قابل‌تشخیص</th></tr></thead><tbody>';foreach($historicalServices as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.fa($r['uses_count']).'</td><td>'.fa($r['patients']).'</td><td>'.money($r['amount']).'</td></tr>';echo '</tbody></table></div></section>';
  $sw='s.starts_at>=? AND s.starts_at<DATE_ADD(?,INTERVAL 1 DAY)'.($tid?' AND s.therapist_id='.$tid:'').($clinic?' AND s.clinic_id='.$clinic:'');echo '<section class="panel form-panel"><h2>درآمد خدمات و سهم درمانگران</h2><p class="hint">بر مبنای جلسات انجام‌شده و تعرفه و سهم ثبت‌شده هنگام رزرو. جلسات قدیمی فاقد تعرفه مستقل، مبلغ صفر دارند. این گزارش پرداختِ سهم را تأیید نمی‌کند.</p><div class="table-scroll"><table><thead><tr><th>درمانگر</th><th>جلسات انجام‌شده</th><th>ارزش خدمات</th><th>سهم درمانگر</th><th>سهم کلینیک</th></tr></thead><tbody>';foreach(q("SELECT u.name,COUNT(*) n,SUM(s.price_snapshot) revenue,SUM(s.share_snapshot) share FROM physio_sessions s JOIN staff u ON u.id=s.therapist_id WHERE s.status='done' AND $sw GROUP BY u.id,u.name",$args)->fetchAll() as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.fa($r['n']).'</td><td>'.money($r['revenue']).'</td><td>'.money($r['share']).'</td><td>'.money($r['revenue']-$r['share']).'</td></tr>';echo '</tbody></table></div></section><section class="panel form-panel"><h2>عملکرد خدمات</h2><div class="table-scroll"><table><thead><tr><th>خدمت</th><th>تعداد</th><th>ارزش خدمات انجام‌شده</th></tr></thead><tbody>';foreach(q("SELECT COALESCE(v.name,'ویزیت / خدمت قدیمی') name,COUNT(*) n,SUM(IF(s.status='done',s.price_snapshot,0)) amount FROM physio_sessions s LEFT JOIN services v ON v.id=s.service_id WHERE $sw GROUP BY v.id,v.name",$args)->fetchAll() as $r)echo '<tr><td>'.e($r['name']).'</td><td>'.fa($r['n']).'</td><td>'.money($r['amount']).'</td></tr>';echo '</tbody></table></div><div class="quick-grid">';foreach(q("SELECT s.status,COUNT(*) n FROM physio_sessions s WHERE $sw GROUP BY s.status",$args)->fetchAll() as $r)echo '<div class="summary-box">'.badge($r['status']).'<strong>'.fa($r['n']).'</strong></div>';echo '</div></section><section class="panel form-panel"><h2>گردش روزانه دریافت</h2><div class="table-scroll"><table><thead><tr><th>روز</th><th>خالص دریافتی</th></tr></thead><tbody>';foreach(q("SELECT DATE(x.created_at) day,SUM(x.amount_toman) amount FROM physio_payments x JOIN physio_episodes e ON e.id=x.episode_id WHERE $paywhere GROUP BY DATE(x.created_at) ORDER BY day",$args)->fetchAll() as $r)echo '<tr><td>'.jd($r['day']).'</td><td>'.money($r['amount']).'</td></tr>';echo '</tbody></table></div></section>';}
 if($report||allowed('finance.referral')){echo '<section class="panel form-panel"><h2>سهم‌های معرفی ثبت‌شده</h2>';foreach(q("SELECT r.*,e.fee_toman FROM referral_fees r JOIN physio_episodes e ON e.id=r.episode_id WHERE $where AND r.created_at>=? AND r.created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY r.id DESC",$args)->fetchAll() as $r)echo '<div class="resource-row"><strong>'.e($r['recipient']).'</strong><span>دوره '.fa($r['episode_id']).' · '.money($r['kind']==='percent'?$r['fee_toman']*$r['value']/100:$r['value']).' تومان</span></div>';echo '</section>';}
 if($report){echo '<section class="panel form-panel"><h2>سابقه اصلاحات و ابطال مالی</h2>';foreach(q('SELECT c.*,u.name FROM financial_changes c LEFT JOIN staff u ON u.id=c.actor WHERE c.created_at>=? AND c.created_at<DATE_ADD(?,INTERVAL 1 DAY) ORDER BY c.id DESC',$args)->fetchAll() as $r)echo '<div class="resource-row"><div><strong>تراکنش '.fa($r['payment_id']).' · '.money($r['old_amount']).' ← '.money($r['new_amount']).'</strong><small>'.e($r['reason']).' · '.e($r['name']).' · '.jd($r['created_at']).'</small></div></div>';echo '</section>';}endLayout();}
function dashboardV2():void{need('dashboard');$today=date('Y-m-d');layout('dashboard',user()['role']==='therapist'?'داشبورد درمانگر':'داشبورد مدیریت','برنامه امروز، دسترسی‌های شما و وضعیت کلینیک.');echo '<section class="welcome-banner"><div><span class="welcome-tag">خوش آمدید، '.e(user()['name']).'</span><h2>مراقبت بهتر، با برنامه‌ای روشن</h2><p>'.jd($today,'EEEE، d MMMM yyyy').'</p><div class="banner-actions">';if(allowed('appointments'))echo '<a class="button white" href="/appointment/new">نوبت‌دهی +</a>';if(can('patients'))echo '<a class="button secondary" href="/patients">تمامی مراجعین مجاز</a>';if(can('reports'))echo '<a class="button secondary" href="/reports">گزارش‌های کامل</a>';echo '</div></div></section>';if(can('patients')){echo '<section class="panel form-panel">';liveSearch();echo '</section>';}$rows=can('patients')?sessions('DATE(s.starts_at)=?',[$today],500):[];echo '<div class="stats-grid three"><article class="stat-card"><span>نوبت‌های امروز در دسترس شما</span><strong>'.fa(count($rows)).'</strong></article>';if(can('patients'))echo '<article class="stat-card"><span>مراجعین مجاز</span><strong>'.fa(q('SELECT COUNT(*) FROM patients p WHERE p.active=1 AND '.patientScope())->fetchColumn()).'</strong></article>';if(allowed('finance.history'))echo '<article class="stat-card"><span>خالص دریافتی امروز (تومان)</span><strong>'.money(q('SELECT COALESCE(SUM(amount_toman),0) FROM physio_payments WHERE voided=0 AND DATE(created_at)=?',[$today])->fetchColumn()).'</strong></article>';echo '</div>';if(can('patients')){echo '<section class="panel"><div class="panel-header"><h2>برنامه امروز</h2></div>';sessionTable($rows);echo '</section>';}echo '<div class="quick-grid">';foreach(['staff'=>['همکاران و دسترسی‌ها','/staff'],'services'=>['خدمات و پکیج‌ها','/services'],'inventory'=>['انبار و کالا','/inventory'],'sms'=>['پیامک‌ها و یادآوری‌ها','/sms'],'labels'=>['لیبل‌های مراجعین','/labels'],'forms'=>['فرم‌ها','/forms'],'finance'=>['امور مالی','/finance'],'reports'=>['درآمد و عملکرد','/reports'],'settings'=>['تنظیمات کلینیک','/settings']] as $k=>$v)if(can($k))echo '<a href="'.$v[1].'">'.icon('grid').'<strong>'.$v[0].'</strong></a>';echo '</div>';endLayout();}
function patientExtras($pid,$p):void{if(user()['role']==='admin'){foreach(q('SELECT id FROM import_records WHERE pid=?',[$pid])->fetchAll() as $ir)echo '<a class="button secondary" href="/imports?record='.$ir['id'].'">مشاهده آرشیو منتقل‌شده از بقراط</a>';}echo '<div class="actions" style="margin-bottom:20px">';if(can('forms'))echo '<a class="button secondary" href="/forms?pid='.$pid.'">فرم‌های مراجعه</a>';if(allowed('patients.delete')){formstart('archive_patient');hidden('pid',$pid);echo '<button class="button secondary" data-confirm="پرونده بایگانی شود؟">بایگانی پرونده</button></form>';}echo '</div>';if(allowed('patients.edit')){echo '<details class="panel form-panel"><summary>مسئول پرونده و لیبل</summary>';formstart('patient_assignment');hidden('pid',$pid);echo '<div class="form-grid">';selectfield('providerID','مسئول پرونده',options('staff','active=1 AND deleted=0'),$p['providerID'],'این همکار در محدوده مراجع مرتبط به پرونده دسترسی خواهد داشت.');selectfield('label_id','لیبل',options('labels','active=1 AND deleted=0'),$p['label_id']??0,'لیبل پیشنهادی نوبت‌های این مراجعه.');echo '</div>';formend('ذخیره','/patient?id='.$pid);echo '</details>';}}
